from retry import with_retries
n = []
def fn():
    n.append(1)
    raise ValueError(len(n))
try:
    with_retries(fn, 3)
except ValueError as e:
    assert e.args == (3,) and len(n) == 3, (e.args, n)
else:
    raise SystemExit(1)

