import ast, sys
src = open('retry.py').read()
tree = ast.parse(src)
banned = {'socket', 'time', 'os', 'random', 'datetime', 'urllib', 'requests', 'pathlib', 'shutil', 'subprocess'}
for n in ast.walk(tree):
    if isinstance(n, ast.Import) and any(a.name.split('.')[0] in banned for a in n.names):
        sys.exit(1)
    if isinstance(n, ast.ImportFrom) and (n.module or '').split('.')[0] in banned:
        sys.exit(1)
    if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id in {'open', 'float', 'input'}:
        sys.exit(1)
    if isinstance(n, ast.Constant) and isinstance(n.value, float):
        sys.exit(1)
    if isinstance(n, ast.BinOp) and isinstance(n.op, ast.Div):
        sys.exit(1)
